import re

def identify_spans(sentence):
    spans = []
    claims = re.findall(r'Senator [A-Z][a-z]+\'[s]? [A-Za-z]+', sentence)
    premises = re.findall(r'the [A-Z][a-z]+ [A-Za-z]+ is/are [A-Za-z]+', sentence)

    for claim in claims:
        if claim in sentence:
            spans.append(f'<claim>{claim}</claim>')

    for premise in premises:
        if premise in sentence:
            spans.append(f'<premise>{premise}</premise>')

    return ''.join(spans + [word for word in sentence.split() if word not in spans])

sentence = "I'll just make a quick comment about vouchers in D.C. Senator McCain's absolutely right : The D.C. school system is in terrible shape, and it has been for a very long time. And we've got a wonderful new superintendent there who's working very hard with the young mayor there to try..."
print(identify_spans(sentence))
```
