import re

def identify_spans(sentence):
    sentence = sentence.strip()
    if sentence.lower().startswith('hm') or sentence.lower().endswith('hm'):
        return sentence
    pattern = r'\b(who|what|when|where|why|how|that)\b'
    matches = re.findall(pattern, sentence)
    if matches:
        for match in matches:
            if match.lower() == 'that':
                sentence = re.sub(rf'\b{match}\b', f'<premise>{match}</premise>', sentence)
            else:
                sentence = re.sub(rf'\b{match}\b', f'<claim>{match}</claim>', sentence)
    return sentence

